      return value;
    });

    // Шаг 2: фоновая загрузка (сеть → БД → UI update).
    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> freshData) {
      if (!mounted) return;
      setState(() => _newsListFuture = Future.value(freshData));
    });
