import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<NewsModel>> _newsListFuture;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  /// Паттерн cache-then-network (конвенция v2, I.2):
  /// 1. Мгновенно показать кэш из БД.
  /// 2. Параллельно в фоне запросить сеть и обновить список по приходу ответа.
  void _initData() {
    final newsRepository = context.read<NewsRepository>();

    // Шаг 1: мгновенный кэш (БД) — без network-вызова.
    _newsListFuture = newsRepository.loadNewsFeed(const NewsFeedFilter.all).then((List<NewsModel> value) {
      _scaleController.forward();
      return value;
    });

    // Шаг 2: фоновая загрузка (сеть → БД → UI update).
    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> freshData) {
      if (!mounted) return;
      setState(() => _newsListFuture = Future.value(freshData));
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: FutureBuilder<List<NewsModel>>(
        future: _newsListFuture,
        builder: (BuildContext ctx, AsyncSnapshot<List<NewsModel>> snapshot) {
          final List<NewsModel>? data = snapshot.data;

          if (snapshot.connectionState != ConnectionState.done || data == null) {
            // Пока кэш загружается из БД — показываем индикатор.
            return const Center(child: CircularProgressIndicator());
          }

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (BuildContext ctx, int index) {
                final NewsModel news = data[index];

                return Padding(
                  key: ValueKey(news.link),
                  padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}

