30:     _scaleController.dispose();
31:     super.dispose();
32:   }
33: 
34:   void _initAnimation() {
35:     _scaleController = AnimationController(
36:       vsync: this,
37:       duration: const Duration(milliseconds: 200),
38:     );
39:     _scaleAnimation = _tween.animate(_scaleController);
40:   }
41: 
42:   /// Паттерн cache-then-network (конвенция v2, I.2):
43:   /// 1. Мгновенно показать кэш из БД.
44:   /// 2. Параллельно в фоне запросить сеть и обновить список по приходу ответа.
45:   void _initData() {
46:     final newsRepository = context.read<NewsRepository>();
47: 
48:     // Шаг 1: мгновенный кэш из БД (без сетевого вызова).
49:     _newsListFuture = newsRepository.loadNewsFeed(NewsFeedFilter()).then((List<NewsModel> value) {
50:       _scaleController.forward();
51:       return value;
52:     });
53: 
54:     // Шаг 2: фоновый fetch (сеть → запись в кэш → обновление UI).
55:     newsRepository.loadNewsFeed(NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> freshData) {
56:       if (!mounted) return;
57:       setState(() {
58:         _newsListFuture = Future.value(freshData);
59:       });
60:     });
61:   }
62: 
63:   @override
64:   Widget build(BuildContext context) {
65:     return Scaffold(
66:       appBar: AppBar(title: Text(context.loc.news)),
67:       body: FutureBuilder<List<NewsModel>>(
68:         future: _newsListFuture,
69:         builder: (BuildContext ctx, AsyncSnapshot<List<NewsModel>> snapshot) {
70:           final List<NewsModel>? data = snapshot.data;
71: 
72:           if (snapshot.connectionState != ConnectionState.done || data == null) {
73:             // Пока кэш загружается из БД — показываем индикатор.
74:             return const Center(child: CircularProgressIndicator());
75:           }
76: 
77:           return ScaleTransition(
78:             scale: _scaleAnimation,
79:             child: ListView.builder(
80:               itemCount: data.length,
81:               itemBuilder: (BuildContext ctx, int index) {
82:                 final NewsModel news = data[index];
83: 
84:                 return Padding(
85:                   key: ValueKey(news.link),
86:                   padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
87:                   child: NewsCard(model: news),
88:                 );
89:               },
90:               padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
91:             ),
92:           );
93:         },
94:       ),
95:     );
96:   }
97: }
